BEGIN;
INSERT INTO mission_bridge_permissions(key,description) VALUES('operations.manage','Manage MissionBridge operations'),('operations.export','Export authorized operational data'),('operations.campaign','Send reviewed unsubscribable communications') ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_role_permissions(role_key,permission_key) VALUES('program_manager','operations.manage'),('program_manager','operations.campaign'),('platform_admin','operations.manage'),('platform_admin','operations.export'),('platform_admin','operations.campaign') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS mission_bridge_bulk_imports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,program_id TEXT NOT NULL,source_name TEXT NOT NULL,row_count INTEGER NOT NULL DEFAULT 0,valid_consent_rows INTEGER NOT NULL DEFAULT 0,rejected_rows INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'validating',created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_bulk_import_rows(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,import_id UUID NOT NULL REFERENCES mission_bridge_bulk_imports(id),participant_ref TEXT NOT NULL,consent_source_reference TEXT,valid BOOLEAN NOT NULL DEFAULT FALSE,rejection_reason TEXT);
CREATE TABLE IF NOT EXISTS mission_bridge_data_exports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,requested_by TEXT NOT NULL,export_type TEXT NOT NULL,filters JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'requested',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_message_templates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,faith_content BOOLEAN NOT NULL DEFAULT FALSE,review_status TEXT NOT NULL DEFAULT 'draft',unsubscribe_required BOOLEAN NOT NULL DEFAULT TRUE,reviewed_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(unsubscribe_required=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_campaigns(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,program_id TEXT NOT NULL,template_id UUID NOT NULL REFERENCES mission_bridge_message_templates(id),created_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',recipient_count INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_unsubscribes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,scope TEXT NOT NULL DEFAULT 'all_campaigns',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,scope));
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_bulk_imports','mission_bridge_bulk_import_rows','mission_bridge_data_exports','mission_bridge_message_templates','mission_bridge_campaigns','mission_bridge_unsubscribes'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
